import {
    MY_FOLLOWERS_SEARCH_URL_CHANGE,
    MY_FOLLOWERS_SEARCH_SUBMIT_ENABLE,
    MY_FOLLOWERS_SEARCH_SUBMIT_DISABLE,
    MY_FOLLOWERS_SEARCH_SUBMITTED,
    MY_FOLLOWERS_SEARCH_NO_RESULTS,
    MY_FOLLOWERS_SEARCH_OTHER_ERROR,
    MY_FOLLOWERS_SEARCH_SUCCESS,
    MY_FOLLOWERS_SELECTED_ROWS_CHANGE,
    MY_FOLLOWERS_SEARCH_UNKNOWN_ERROR

} from '../actions/myFollowersActions';


export default function myFollowersReducer(state, action) {
  
  switch(action.type) {

      
    case MY_FOLLOWERS_SEARCH_SUBMITTED:
      return {
        ...state,
            showMyFollowersTable: false,
            showMyFollowersSearchSubmitButton: false,
            showMyFollowersSearchSubmitLoadingButton: true,
            enableMyFollowersSearchInput: false,
            showErrorAlert: false,
            showSuccessAlert: false,
            showInfoAlert: false
        
      };
    
    case MY_FOLLOWERS_SEARCH_NO_RESULTS:
        //console.log("sc login error - reducer");
        //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none';
      return {
        ...state,
        errorAlertText: '',
        errorAlertLinkText: '',
        showInfoAlert: false,
        showSuccessAlert: true,
        showErrorAlert: true,
        showMyFollowersSearchSubmitButton: true,
        showMyFollowersSearchSubmitLoadingButton: false,
        enableMyFollowersSearchFormInputs : true,
        enableMyFollowersSearchSubmitButton: true, 
        showMyFollowersTable: true,
        successAlertText: "But there were no myFollowers found for this track."
        
      };
      
    case MY_FOLLOWERS_SEARCH_OTHER_ERROR:
         //console.log("sc cookie error - reducer");
      return {
        ...state,
        showInfoAlert: false,
        showLoginForm: false,
        errorAlertText: "Something went wrong. Please try again, or contact support.",
        errorAlertLinkText: '',
        showErrorAlert: true,
        enableMyFollowersSearchFormInputs : true,
        enableMyFollowersSearchSubmitButton: true, 
        showMyFollowersSearchSubmitButton: true,
        showMyFollowersSearchSubmitLoadingButton: false
      };
      
      
    case MY_FOLLOWERS_SEARCH_SUCCESS:
         //console.log("sc myFollowersSearch success - reducer");
         //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none'
      return {
        ...state,
        showInfoAlert: false,
        showErrorAlert: false,
        showMyFollowersSearchSubmitLoadingButton: false,
        showMyFollowersSearchSubmitButton: true,
        enableMyFollowersSearchSubmitButton: true, 
        enableMyFollowersSearchInput: true,
        myFollowerData: action.myFollowerData,
        showMyFollowersTable: true,
        successAlertText: "Found " + action.myFollowerData.length + ' myFollowers.',
    
      };
      
    case MY_FOLLOWERS_SEARCH_UNKNOWN_ERROR:
        //console.log('reducer other error')
      return {
        ...state,
          showMyFollowersSearchSubmitButton: true,
          showMyFollowersSearchSubmitLoadingButton: false,
          enableMyFollowersSearchInput: true,
          showErrorAlert: true,
          errorAlertText: "Something went wrong. Please contact support."
              
      };
      
      
    case MY_FOLLOWERS_SELECTED_ROWS_CHANGE:
         //console.log("MY_FOLLOWERS_SELECTED_ROWS_CHANGE - reducer");
         //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none'
      return {
        ...state,
        selectedMyFollowers: action.selectedMyFollowers
    
      };
    
    default:
      // ALWAYS have a default case in a reducer
      return state;
  }
}
